Sdb* process_verneed_section(ELFOBJ *bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb *sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    void *data = elf_getdata(bin, shdr, &sz);
    if (!data) {
        sdb_free(sdb);
        return NULL;
    }

    Elf_(Verneed) *verneed = data;
    size_t offset = 0;
    while (offset < sz) {
        Elf_(Verneed) *vn = (Elf_(Verneed)*)((char*)data + offset);
        if (vn->vn_version == 0) {
            break;
        }

        for (int i = 0; i < vn->vn_cnt; i++) {
            Elf_(VerneedAux) *vna = (Elf_(VerneedAux)*)((char*)vn + sizeof(Elf_(Verneed)) + i * sizeof(Elf_(VerneedAux)));
            char *name = sdb_arena_string(vna->vna_name);
            char *key = sdb_fmt("version.%s", name);
            sdb_set(sdb, key, NULL, 0);
        }

        offset += vn->vn_next;
    }

    return sdb;
}

Sdb* parse_verneed_section(ELFOBJ* bin, Elf_Shdr* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    gsize data_size;
    void* data = elf_getdata(bin, shdr, &data_size);
    if (!data || data_size != (gsize)sz) {
        sdb_free(sdb);
        return NULL;
    }

    Elf_Verneed* verneed = data;
    while ((gsize)((Elf_Verneed*)verneed - (Elf_Verneed*)data) < (gsize)sz) {
        const char* name = elf_strptr(bin, shdr->sh_link, verneed->vn_file);
        if (!name) {
            sdb_free(sdb);
            return NULL;
        }

        Elf_Vernaux* vna = (Elf_Vernaux*)((Elf_Verneed*)verneed + 1);
        while ((gsize)((Elf_Vernaux*)vna - (Elf_Verneed*)data) < (gsize)sz) {
            if (vna->vna_hash == 0) {
                break;
            }

            const char* version = elf_strptr(bin, shdr->sh_link, vna->vna_name);
            if (!version) {
                sdb_free(sdb);
                return NULL;
            }

            char key[128];
            snprintf(key, sizeof(key), "version.%s", version);
            sdb_set(sdb, key, name, 0);

            vna = (Elf_Vernaux*)((Elf_Vernaux*)vna + 1);
        }

        verneed = (Elf_Verneed*)((Elf_Verneed*)verneed + verneed->vn_cnt);
    }

    return sdb;
}

Sdb* process_verneed_section(ELFOBJ *bin, Elf_Shdr *shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb *sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    void *data = elf_section_data(bin, shdr);
    if (!data) {
        sdb_free(sdb);
        return NULL;
    }

    Elf_Verneed *verneed = data;
    size_t i = 0;
    while (i < sz) {
        if (verneed->vn_version != 1) {
            i += sizeof(Elf_Verneed);
            continue;
        }

        const char *version_name = elf_string(bin, shdr->sh_link, verneed->vn_file);
        if (!version_name) {
            sdb_free(sdb);
            return NULL;
        }

        Elf_Verneed *aux = (Elf_Verneed*)((char*)verneed + sizeof(Elf_Verneed));
        size_t j = 0;
        while (j < verneed->vn_cnt) {
            if (aux->vna_next <= 0) {
                break;
            }

            const char *aux_name = elf_string(bin, shdr->sh_link, aux->vna_name);
            if (!aux_name) {
                sdb_free(sdb);
                return NULL;
            }

            char key[256];
            snprintf(key, sizeof(key), "%s.%s", version_name, aux_name);
            sdb_num_set(sdb, key, 1, 0);

            j += aux->vna_next;
            aux = (Elf_Verneed*)((char*)aux + aux->vna_next);
        }

        i += sizeof(Elf_Verneed) + (verneed->vn_cnt * sizeof(Elf_Verneed));
        verneed = (Elf_Verneed*)((char*)data + i);
    }

    return sdb;
}

#include <stdlib.h>
#include <string.h>

Sdb* process_verneed_section(ELFOBJ* bin, Elf_(Shdr)* shdr, int sz) {
    if (!bin || !shdr || sz <= 0) {
        return NULL;
    }

    Sdb* sdb = sdb_new0();
    if (!sdb) {
        return NULL;
    }

    void* verneed_data = elf_get_data(bin, shdr, sz);
    if (!verneed_data) {
        sdb_free(sdb);
        return NULL;
    }

    char* section_name = elf_get_section_name(bin, shdr);
    if (!section_name) {
        sdb_free(sdb);
        free(verneed_data);
        return NULL;
    }

    Elf_(Verneed)* verneed_entry = (Elf_(Verneed)*)verneed_data;
    while ((size_t)((Elf_(Verneed)*)verneed_entry - (Elf_(Verneed)*)verneed_data) < sz) {
        if (verneed_entry->vn_version != 1) {
            sdb_free(sdb);
            free(verneed_data);
            free(section_name);
            return NULL;
        }

        char* version_name = elf_get_string(bin, verneed_entry->vn_file);
        if (!version_name) {
            sdb_free(sdb);
            free(verneed_data);
            free(section_name);
            return NULL;
        }

        char* key = malloc(strlen(section_name) + strlen(version_name) + 2);
        if (!key) {
            sdb_free(sdb);
            free(verneed_data);
            free(section_name);
            free(version_name);
            return NULL;
        }
        sprintf(key, "%s.%s", section_name, version_name);

        if (!sdb_set(sdb, key, "1", 0)) {
            free(key);
            sdb_free(sdb);
            free(verneed_data);
            free(section_name);
            free(version_name);
            return NULL;
        }

        Elf_(VerneedAux)* aux = (Elf_(VerneedAux*)((char*)verneed_entry + sizeof(Elf_(Verneed))));
        while ((size_t)((Elf_(VerneedAux)*)aux - (Elf_(VerneedAux)*)verneed_data) < sz) {
            char* aux_name = elf_get_string(bin, aux->vna_name);
            if (!aux_name) {
                free(key);
                sdb_free(sdb);
                free(verneed_data);
                free(section_name);
                free(version_name);
                return NULL;
            }

            char* aux_key = malloc(strlen(section_name) + strlen(version_name) + strlen(aux_name) + 4);
            if (!aux_key) {
                free(key);
                free(aux_name);
                sdb_free(sdb);
                free(verneed_data);
                free(section_name);
                free(version_name);
                return NULL;
            }
            sprintf(aux_key, "%s.%s.%s", section_name, version_name, aux_name);

            if (!sdb_set(sdb, aux_key, "1", 0)) {
                free(key);
                free(aux_key);
                free(aux_name);
                sdb_free(sdb);
                free(verneed_data);
                free(section_name);
                free(version_name);
                return NULL;
            }

            free(aux_key);
            free(aux_name);
            aux = (Elf_(VerneedAux*)((char*)aux + sizeof(Elf_(VerneedAux))));
        }

        free(version_name);
        free(key);
        verneed_entry = (Elf_(Verneed*)((char*)verneed_entry + verneed_entry->vn_next));
    }

    free(verneed_data);
    free(section_name);
    return sdb;
}
